//! StoryLoop on phones: the engine as a native library for the Android app in
//! `android/`, with Kotlin bindings generated by
//! [UniFFI](https://mozilla.github.io/uniffi-rs).
//!
//! The app shows a timeline laid out the way phone editors lay theirs out:
//! one gapless main track of photos and videos, overlay rows above it —
//! stickers, text, drawing — and audio rows. Every edit is one command
//! (JSON, written by Kotlin's kotlinx.serialization) applied to the session,
//! and every call returns a [`TimelineView`] snapshot the UI renders.
//!
//! Time crosses the bridge as whole microseconds, never floating-point
//! seconds; the engine's document keeps seconds only as microseconds.
//!
//! Threading: every method may be called from any thread. The session's lock
//! is held only while a call reads or edits the document. The app calls in
//! from its own threads, never from the main one.

#![deny(unsafe_code)]

use std::sync::{Arc, Mutex, MutexGuard};

use storyloop_core::{Clip, ClipKind, Command, Engine, EngineError, Format, LaneKind};

uniffi::setup_scaffolding!();

/// What went wrong, as a sentence the user can act on.
#[derive(Debug, thiserror::Error, uniffi::Error)]
#[uniffi(flat_error)]
pub enum MobileError {
    /// The engine refused or failed: bad input, an unknown format name.
    #[error("{0}")]
    Failed(String),
}

impl From<EngineError> for MobileError {
    fn from(e: EngineError) -> Self {
        MobileError::Failed(e.to_string())
    }
}

impl From<serde_json::Error> for MobileError {
    fn from(e: serde_json::Error) -> Self {
        MobileError::Failed(format!("bad command: {e}"))
    }
}

/// One clip as the timeline UI shows it.
#[derive(Debug, Clone, uniffi::Record)]
pub struct ClipInfo {
    pub id: u64,
    /// The lane the clip sits on: "audio", "sticker", "text", "draw" or "main".
    pub lane: String,
    /// What the clip is: "media", "text", "sticker", "draw" or "audio".
    pub kind: String,
    pub start_us: i64,
    pub duration_us: i64,
    /// The file on the device, for media and audio clips.
    pub media_path: Option<String>,
    /// Whether a media clip is a video (false and null for the rest).
    pub is_video: Option<bool>,
    /// What a text clip says.
    pub text: Option<String>,
    /// The emoji a sticker clip shows.
    pub glyph: Option<String>,
    /// What an audio clip is titled.
    pub name: Option<String>,
    /// Normalized canvas position (0..1), for text and stickers.
    pub x: Option<f32>,
    pub y: Option<f32>,
}

/// A full snapshot of the timeline, returned after every call.
#[derive(Debug, Clone, uniffi::Record)]
pub struct TimelineView {
    /// The canvas format: "reel", "portrait", "square" or "landscape".
    pub format: String,
    /// Width divided by height of the canvas.
    pub ratio: f32,
    /// The project's length, in microseconds.
    pub duration_us: i64,
    pub clips: Vec<ClipInfo>,
    pub can_undo: bool,
    pub can_redo: bool,
}

fn lane_name(lane: LaneKind) -> &'static str {
    match lane {
        LaneKind::Audio => "audio",
        LaneKind::Sticker => "sticker",
        LaneKind::Text => "text",
        LaneKind::Draw => "draw",
        LaneKind::Main => "main",
    }
}

fn clip_info(lane: LaneKind, clip: &Clip) -> ClipInfo {
    let (kind, media_path, is_video, text, glyph, name, x, y) = match &clip.kind {
        ClipKind::Media { path, is_video } => {
            ("media", Some(path.clone()), Some(*is_video), None, None, None, None, None)
        }
        ClipKind::Text { content, x, y, .. } => {
            ("text", None, None, Some(content.clone()), None, None, Some(*x), Some(*y))
        }
        ClipKind::Sticker { glyph, x, y, .. } => {
            ("sticker", None, None, None, Some(glyph.clone()), None, Some(*x), Some(*y))
        }
        ClipKind::Draw { strokes: _ } => ("draw", None, None, None, None, None, None, None),
        ClipKind::Audio { path, name } => {
            ("audio", Some(path.clone()), None, None, None, Some(name.clone()), None, None)
        }
    };
    ClipInfo {
        id: clip.id,
        lane: lane_name(lane).into(),
        kind: kind.into(),
        start_us: clip.start_us,
        duration_us: clip.duration_us,
        media_path,
        is_video,
        text,
        glyph,
        name,
        x,
        y,
    }
}

fn view(engine: &Engine) -> TimelineView {
    let doc = engine.document();
    TimelineView {
        format: doc.format.name().into(),
        ratio: doc.format.ratio(),
        duration_us: doc.duration_us,
        clips: doc.clips().map(|(lane, c)| clip_info(lane, c)).collect(),
        can_undo: engine.can_undo(),
        can_redo: engine.can_redo(),
    }
}

fn lock(engine: &Mutex<Engine>) -> Result<MutexGuard<'_, Engine>, MobileError> {
    engine.lock().map_err(|_| MobileError::Failed("the session is busy".into()))
}

/// The editing session for one project: the entry point Kotlin talks to.
#[derive(uniffi::Object)]
pub struct EditorSession {
    inner: Mutex<Engine>,
}

#[uniffi::export]
impl EditorSession {
    /// Opens a fresh project for `format` ("reel", "portrait", "square" or
    /// "landscape"), starting 15 s long.
    #[uniffi::constructor]
    pub fn new(format: String) -> Result<Arc<Self>, MobileError> {
        let format =
            Format::from_name(&format).ok_or_else(|| MobileError::Failed(format!("unknown format: {format}")))?;
        Ok(Arc::new(EditorSession { inner: Mutex::new(Engine::new(format)) }))
    }

    /// Applies one command (JSON as kotlinx.serialization writes it) and
    /// returns the new view. One call is one undo step.
    pub fn apply(&self, command_json: String) -> Result<TimelineView, MobileError> {
        let command: Command = serde_json::from_str(&command_json)?;
        let mut engine = lock(&self.inner)?;
        engine.apply(command)?;
        Ok(view(&engine))
    }

    /// Undoes the last command and returns the view as it was before it.
    pub fn undo(&self) -> Result<TimelineView, MobileError> {
        let mut engine = lock(&self.inner)?;
        if !engine.undo() {
            return Err(MobileError::Failed("nothing to undo".into()));
        }
        Ok(view(&engine))
    }

    /// Re-applies the last undone command and returns the view as it was.
    pub fn redo(&self) -> Result<TimelineView, MobileError> {
        let mut engine = lock(&self.inner)?;
        if !engine.redo() {
            return Err(MobileError::Failed("nothing to redo".into()));
        }
        Ok(view(&engine))
    }

    /// The current view, without changing anything.
    pub fn timeline(&self) -> TimelineView {
        let engine = self.inner.lock().unwrap_or_else(|p| p.into_inner());
        view(&engine)
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_new_session_reports_an_empty_reel() {
        let session = EditorSession::new("reel".into()).unwrap();
        let view = session.timeline();
        assert_eq!(view.format, "reel");
        assert_eq!(view.duration_us, 15_000_000);
        assert!(view.clips.is_empty());
        assert!(!view.can_undo);
    }

    #[test]
    fn applying_a_command_lands_a_clip_and_an_undo_step() {
        let session = EditorSession::new("reel".into()).unwrap();
        let view = session
            .apply(r#"{"type":"add_text","content":"hey","at_us":0,"duration_us":3000000}"#.into())
            .unwrap();
        assert_eq!(view.clips.len(), 1);
        assert_eq!(view.clips[0].lane, "text");
        assert_eq!(view.clips[0].text.as_deref(), Some("hey"));
        assert!(view.can_undo);
        let undone = session.undo().unwrap();
        assert!(undone.clips.is_empty());
    }

    #[test]
    fn a_bad_format_is_refused() {
        assert!(EditorSession::new("dailymotion".into()).is_err());
    }
}
